init_analytics();
async function saveRelaySuccess(token, flow) {
  saveOidcTokens({
    accessToken: token.accessToken,
    refreshToken: token.refreshToken,
    expireAt: token.expireAt
  });
  saveToken(token.bookipiToken);
  const profile = await saveCompanyFromProfile();
  await loginCompleted({
    login_flow: flow,
    has_company: profile.companies.length > 0
  });
  return profile;
}
function successPayload(profile) {
  const company = profile.defaultCompany?.name ?? null;
  return {
    success: true,
    ...profile.email ? { email: profile.email } : {},
    ...company ? { company } : {},
    action: "Logged in. Resume whatever the user asked for before the login detour; if there was nothing, show the main menu."
  };
}
var sleep2 = (ms) => new Promise((r) => setTimeout(r, ms));
var DEFAULT_WAIT_MS = 11e4;
async function saveCompanyFromProfile() {
  const profile = await persistLoginProfile();
  if (profile.companies.length > 1 && profile.defaultCompany) {
    const defaultCo = profile.defaultCompany;
    const others = profile.companies.slice(1).map((c) => `${c.name} [${c.currency ?? "\u2014"}]`).join(", ");
    console.error(`Warning: You have ${profile.companies.length} companies. Defaulting to: ${defaultCo.name} [${defaultCo.currency ?? "\u2014"}]`);
    console.error(`Other companies: ${others}`);
    console.error(`Switch default with: bookipi company set <id-or-name>`);
  }
  return profile;
}
var loginCommand = new Command("login").description("Login to Bookipi via browser (PKCE OAuth)").option(
  "--ref <code>",
  "Referral code the user signed up with (a creator's or campaign's). Stored once; the first code wins."
).option(
  "--relay-start",
  "Step 1 of the split relay flow: register a relay session and print the auth URL + sessionId. Exits immediately. Used by AI orchestrators (Cowork skill) so the bookipi process doesn't have to stay alive for the 5-min poll window."
).option(
  "--relay-resume <sessionId>",
  'Step 2 of the split relay flow: single-poll the relay server with <sessionId>, save the token if the user has authorized, and exit. Run periodically until {"success":true}.'
).option(
  "--relay-wait <sessionId>",
  'Step 2 (auto-poll): poll the relay until the user authorizes, then save the token and print {"success":true}. Waits ~110s by default \u2014 long enough to cover most logins, short enough to always return inside a 2-minute tool budget. On {"status":"pending"} just run it again; the result says so.'
).option(
  "--wait-seconds <seconds>",
  "Widen (or narrow) --relay-wait's window. Use it only when the call cannot be killed \u2014 e.g. a background task, where ~290 covers the whole 5-minute session in one call. A killed process prints nothing at all, which is why this is not the default."
).action(async (opts) => {
  try {
    if (opts.relayStart) {
      if (opts.relayResume) {
        failWith("--relay-start and --relay-resume are mutually exclusive");
      }
      const result = await startRelayLogin();
      console.log(
        JSON.stringify({
          ...result,
          next: `bookipi login --relay-wait ${result.sessionId}`,
          // The agent-facing path. Without this the caller got {url,
          // sessionId} and nothing telling it a second step exists, which is
          // the other half of "the link appeared and then nothing happened".
          action: "Share the url with the user as a clickable markdown link, then run `next` \u2014 it waits for them to authorize and detects it. Do not ask the user to confirm when they are done."
        })
      );
      process.exit(0);
    }
    if (opts.relayResume) {
      try {
        const result = await resumeRelayLogin(opts.relayResume);
        if (result.status === "pending") {
          console.log(JSON.stringify({ status: "pending" }));
          process.exit(0);
        }
        const profile2 = await saveRelaySuccess(result.token, "relay_resume");
        console.log(JSON.stringify(successPayload(profile2)));
        process.exit(0);
      } catch (err2) {
        const msg = err2?.message ?? "";
        if (msg.includes("Session expired") || msg.includes("Unknown session")) {
          console.log(JSON.stringify({ error: msg }));
          process.exit(3);
        }
        emitError(err2, { json: true });
      }
    }
    if (opts.relayWait) {
      const POLL_MS = 7e3;
      const startedAt = Date.now();
      const stored = getPendingRelaySession();
      const sessionEndsAt = stored ? stored.createdAt + SESSION_MAX_AGE_MS : startedAt + SESSION_MAX_AGE_MS;
      let capMs = DEFAULT_WAIT_MS;
      if (opts.waitSeconds !== void 0) {
        const seconds = Number(opts.waitSeconds);
        if (!Number.isFinite(seconds) || seconds <= 0) {
          failWith("--wait-seconds must be a positive number of seconds");
        }
        capMs = seconds * 1e3;
      }
      const deadline = Math.min(sessionEndsAt, startedAt + capMs);
      const reportPending = () => {
        const expiresInMs = Math.max(0, sessionEndsAt - Date.now());
        console.log(
          JSON.stringify({
            status: "pending",
            waitedMs: Date.now() - startedAt,
            sessionExpiresInMs: expiresInMs,
            next: `bookipi login --relay-wait ${opts.relayWait}`,
            // Same reasoning as successPayload: the next move is decided
            // after this process is gone, so it ships with the result.
            action: expiresInMs > 0 ? "Not authorized yet. Run `next` again now \u2014 do NOT ask the user whether they finished, this command detects it." : "The login session has expired. Start over with `bookipi login --relay-start`."
          })
        );
        process.exit(0);
      };
      while (true) {
        let result;
        try {
          result = await resumeRelayLogin(opts.relayWait);
        } catch (err2) {
          const msg = err2?.message ?? "";
          if (msg.includes("Session expired") || msg.includes("Unknown session") || msg.includes("State mismatch")) {
            console.log(
              JSON.stringify({
                error: msg,
                action: "Start over: bookipi login --relay-start"
              })
            );
            process.exit(3);
          }
          if (Date.now() >= deadline) reportPending();
          await sleep2(Math.min(POLL_MS, deadline - Date.now()));
          continue;
        }
        if (result.status === "completed") {
          const profile2 = await saveRelaySuccess(result.token, "relay_wait");
          console.log(JSON.stringify(successPayload(profile2)));
          process.exit(0);
        }
        if (Date.now() >= deadline) reportPending();
        await sleep2(Math.min(POLL_MS, deadline - Date.now()));
      }
    }
    if (!process.stdout.isTTY) {
      const result = await startRelayLogin();
      console.log(
        JSON.stringify({
          ...result,
          next: `bookipi login --relay-wait ${result.sessionId}`,
          action: "Share the url with the user as a clickable markdown link, then run `next` \u2014 it waits for them to authorize and detects it. Do not ask the user to confirm when they are done."
        })
      );
      process.exit(0);
    }
    const token = await relayLogin();
    const profile = await saveRelaySuccess(token, "terminal");
    console.log(JSON.stringify(successPayload(profile)));
    process.exit(0);
  } catch (err2) {
    emitError(err2, { json: opts?.json });
  }
});

