// src/usecases/customer/resolveCustomer.ts
async function resolveCustomerId(value) {
  const registry3 = HandleRegistry.getInstance();
  if (value.startsWith("@")) {
    return registry3.resolve(value);
  }
  if (/^[a-f0-9]{24}$/i.test(value)) {
    return value;
  }
  const data = await listCustomers({ search: value, perPage: 10 });
  const customers = data.searchCustomers?.items || [];
  if (customers.length === 0) {
    throw new Error(
      `No customer found matching "${value}". Pass a handle (@c1), a customer ID, or create one first via 'bookipi customer create'.`
    );
  }
  const normalized = value.trim().toLowerCase();
  const exactMatches = customers.filter((c) => {
    const fullName = [c.firstName, c.lastName].filter(Boolean).join(" ").trim().toLowerCase();
    return (c.companyName ?? "").toLowerCase() === normalized || (c.individualCompanyName ?? "").toLowerCase() === normalized || fullName === normalized || (c.email ?? "").toLowerCase() === normalized;
  });
  if (exactMatches.length === 1) {
    return exactMatches[0]._id;
  }
  if (exactMatches.length > 1) {
    const list2 = exactMatches.map((c) => `  - ${customerLabel(c)} (${c._id})`).join("\n");
    throw new Error(
      `Multiple customers exactly match "${value}". Specify by handle or ID:
${list2}`
    );
  }
  if (customers.length === 1) {
    return customers[0]._id;
  }
  const list = customers.slice(0, 5).map((c) => `  - ${customerLabel(c)} (${c._id})`).join("\n");
  throw new Error(
    `Multiple customers match "${value}" but none exactly. Specify by handle or ID:
${list}`
  );
}
function customerLabel(c) {
  const fullName = [c.firstName, c.lastName].filter(Boolean).join(" ").trim();
  return c.companyName || fullName || c.email || "(unnamed)";
}

