  if (extraFields?.email) record2.email = extraFields.email;
  const created = await createCustomer(record2, companyId);
  const customer = created.customersCreateOne?.record;
  if (!customer) throw new Error("Failed to create customer");
  return { customer, how: "created", createdName: value };
