// src/usecases/invoice/copyInvoice.ts
var CARRIED = [
  "dueIn",
  "note",
  "noteHtml",
  "taxInclusive",
  "taxName",
  "taxPercentage",
  "tax1",
  "discount",
  "discountPercentage",
  "discountAfterTax",
  "shippingCost"
];
function copyItems(source) {
  const items = Array.isArray(source["items"]) ? source["items"] : [];
  return items.map((it2) => ({
    name: it2["name"],
    ...it2["description"] ? { description: it2["description"] } : {},
    ...it2["productCode"] ? { productCode: it2["productCode"] } : {},
    price: it2["price"] ?? 0,
    quantity: it2["quantity"] ?? 1,
    ...it2["discount"] != null ? { discount: it2["discount"] } : {},
    ...it2["enableTax"] != null ? { enableTax: it2["enableTax"] } : {},
    ...it2["enableTax2"] != null ? { enableTax2: it2["enableTax2"] } : {},
    ...it2["taxCode"] ? { taxCode: it2["taxCode"] } : {},
    ...it2["taxRate"] != null ? { taxRate: it2["taxRate"] } : {},
    ...it2["total"] != null ? { total: it2["total"] } : {}
  }));
}
function customerQuery(source) {
  const c = source["customer"] ?? {};
  const full = [c["firstName"], c["lastName"]].filter(Boolean).join(" ");
  return c["companyName"] || full || c["individualCompanyName"] || c["email"] || null;
}
async function copyInvoice(sourceId, opts = {}) {
  if (opts.toCompanyId) {
    const source = await getInvoice(sourceId);
    const targetType2 = opts.type ? resolveDocumentType(opts.type) : documentTypeByCode(source["type"]);
    const query = opts.customer ?? customerQuery(source);
    if (!query) throw new Error("The source invoice has no customer to copy.");
    const srcCust = source["customer"] ?? {};
    const found = await findOrCreateCustomer(
      String(query),
      opts.toCompanyId,
      srcCust["email"] ? { email: String(srcCust["email"]) } : void 0
    );
    const invCustomer = buildInvoiceCustomer(found.customer);
    const no = await getNextInvoiceNumber(targetType2.code, opts.toCompanyId);
    const carry = {};
    for (const k of CARRIED) {
      if (source[k] !== void 0 && source[k] !== null) carry[k] = source[k];
    }
    const created = await createInvoice({
      company: opts.toCompanyId,
      no,
      date: source["date"],
      type: targetType2.code,
      creationMethod: "manual",
      customer: invCustomer,
      customerId: invCustomer["_id"],
      items: copyItems(source),
      ...carry
    });
    const record3 = created.invoicesCreateOne?.record;
    if (!record3) {
      throw new Error("Cross-company copy failed \u2014 the create returned no record.");
    }
    return {
      record: record3,
      converted: targetType2.code !== source["type"],
      crossCompany: true
    };
  }
  const targetType = opts.type ? resolveDocumentType(opts.type) : void 0;
  const newCustomer = opts.customer ? (await findOrCreateCustomer(opts.customer, opts.companyId ?? "")).customer : void 0;
  let record2 = await duplicateInvoice(sourceId, {
    ...opts.timezone ? { creationTimezone: opts.timezone } : {}
  });
  const updateFields = {};
  let converted = false;
  if (targetType && targetType.code !== record2["type"]) {
    updateFields["type"] = targetType.code;
    updateFields["no"] = await getNextInvoiceNumber(targetType.code);
    converted = true;
  }
  if (newCustomer) {
    const customer = buildInvoiceCustomer(newCustomer);
    updateFields["customer"] = customer;
    updateFields["customerId"] = customer["_id"];
    updateFields["recipientEmail"] = customer["email"] || null;
  }
  if (Object.keys(updateFields).length > 0) {
    const data = await updateInvoice(String(record2["_id"]), updateFields);
    record2 = data.invoicesUpdateOne?.record ?? record2;
  }
  return { record: record2, converted, crossCompany: false };
}

