init_tokenStore();
var MONGO_ID = /^[a-f0-9]{24}$/i;
function collect(value, previous) {
  return [...previous, value];
}
function findItemIndex(items, match, flag) {
  if (MONGO_ID.test(match)) {
    const idx = items.findIndex((i) => i._id === match);
    if (idx === -1) throw new Error(`${flag}: no line item with _id ${match}`);
    return idx;
  }
  if (/^\d+$/.test(match)) {
    const idx = Number(match) - 1;
    if (idx < 0 || idx >= items.length) {
      throw new Error(
        `${flag}: position ${match} is out of range (invoice has ${items.length} line item${items.length === 1 ? "" : "s"})`
      );
    }
    return idx;
  }
  const normalized = match.trim().toLowerCase();
  const hits = items.map((item, idx) => ({ item, idx })).filter(({ item }) => (item.name ?? "").toLowerCase() === normalized);
  if (hits.length === 0) {
    const names = items.map((i, n) => `  ${n + 1}. ${i.name}`).join("\n");
    throw new Error(
      `${flag}: no line item named "${match}". Current items:
${names}`
    );
  }
  if (hits.length > 1) {
    throw new Error(
      `${flag}: ${hits.length} line items are named "${match}" \u2014 match by _id or 1-based position instead`
    );
  }
  return hits[0].idx;
}
