// src/usecases/invoice/collectionsPlan.ts
var COLLECTIONS_STAGES = [
  {
    key: "gentle",
    label: "Gentle nudge",
    minDays: 3,
    maxDays: 13,
    subject: "Friendly reminder: invoice {no} ({amount})",
    body: "Hi {name},\n\nJust a friendly reminder that invoice {no} for {amount} was due on {dueDate} \u2014 it's now {days} day(s) overdue. If it's already on its way, thank you, and please ignore this note!\n\nOtherwise, no rush \u2014 whenever you get a moment.\n\nThanks so much."
  },
  {
    key: "firm",
    label: "Firm follow-up",
    minDays: 14,
    maxDays: 29,
    subject: "Overdue: invoice {no} ({amount}) \u2014 {days} days past due",
    body: "Hi {name},\n\nInvoice {no} for {amount} is now {days} days past due (it was due {dueDate}). Could you arrange payment this week? You can pay it directly from the invoice in this email.\n\nIf there's a problem with the invoice, just let me know and I'll sort it out.\n\nThank you."
  },
  {
    key: "final",
    label: "Final notice",
    minDays: 30,
    maxDays: null,
    subject: "Final notice: invoice {no} ({amount}) \u2014 {days} days overdue",
    body: "Hi {name},\n\nInvoice {no} for {amount} is now {days} days overdue (due {dueDate}) and needs attention. You can pay it directly from the invoice in this email.\n\nIf payment can't be made right now, let's talk about a plan \u2014 happy to help. Otherwise we may need to pause new work.\n\nThank you."
  }
];
function classify(daysOverdue2) {
  for (const s of COLLECTIONS_STAGES) {
    if (daysOverdue2 >= s.minDays && (s.maxDays === null || daysOverdue2 <= s.maxDays)) {
      return s;
    }
  }
  return null;
}
function dateLabel(iso) {
  return iso.slice(0, 10);
}
function buildCollectionsPlan(entries, now2 = /* @__PURE__ */ new Date(), fmt = (n) => formatCurrency(n)) {
  const drafts = [];
  const skipped = [];
  for (const e of entries) {
    if (!e.dueDateIso) {
      skipped.push({ invoiceNo: e.invoiceNo, reason: "no due date" });
      continue;
    }
    const due = new Date(e.dueDateIso).getTime();
    if (!Number.isFinite(due)) {
      skipped.push({ invoiceNo: e.invoiceNo, reason: "unparseable due date" });
      continue;
    }
    const daysOverdue2 = daysBetween(e.dueDateIso, now2);
    const stage = classify(daysOverdue2);
    if (!stage) {
      skipped.push({
        invoiceNo: e.invoiceNo,
        reason: daysOverdue2 < COLLECTIONS_STAGES[0].minDays ? `only ${daysOverdue2}d overdue \u2014 too soon to chase` : `no stage for ${daysOverdue2}d`
      });
      continue;
    }
    const vars = {
      no: e.invoiceNo,
      name: e.customerName || "there",
      amount: fmt(e.amountDue),
      days: daysOverdue2,
      dueDate: dateLabel(e.dueDateIso)
    };
    drafts.push({
      ...e,
      daysOverdue: daysOverdue2,
      stage: stage.key,
      stageLabel: stage.label,
      subject: renderTemplate(stage.subject, vars),
      body: renderTemplate(stage.body, vars)
    });
  }
  drafts.sort((a, b) => b.daysOverdue - a.daysOverdue);
  const byStage = { gentle: 0, firm: 0, final: 0 };
  for (const d of drafts) byStage[d.stage]++;
  return { drafts, skipped, byStage };
}

// src/usecases/invoice/runCollections.ts
function normalizeNo(no) {
  return no.trim().toLowerCase().replace(/^inv-/, "");
}
async function runCollections(options = {}, deps = {}) {
  const {
    send = false,
    stage,
    customer: customerFilter,
    limit = 50,
    exclude = [],
    cooldownDays = 7
  } = options;
  const dryRun = !send;
  const fetchOverdue = deps.fetchOverdue ?? fetchOverdueInvoices;
  const doSend = deps.send ?? sendInvoice;
  const nowDate = deps.now ?? /* @__PURE__ */ new Date();
  const excludeSet = new Set(exclude.map(normalizeNo));
  const rawInvoices = await fetchOverdue();
  const entries = rawInvoices.map((inv) => {
    const amountDue = typeof inv.amountDue === "number" ? inv.amountDue : typeof inv.total === "number" ? inv.total : 0;
    return {
      invoiceId: inv._id,
      invoiceNo: inv.no || "N/A",
      customerName: customerName(inv.customer || inv.customerReference, {
        fallback: ""
      }),
      customerEmail: customerEmailFromInvoice(inv) ?? "",
      amountDue,
      dueDateIso: inv.dueDate || null,
      lastSentIso: typeof inv.sent === "string" ? inv.sent : null
    };
  });
  const plan = buildCollectionsPlan(entries, nowDate);
  const outcomes = [];
  let acted = 0;
  for (const draft of plan.drafts) {
    const base = { ...draft, status: "planned" };
    if (stage && draft.stage !== stage) {
      base.status = "skipped";
      base.skipReason = `not in --stage ${stage}`;
      outcomes.push(base);
      continue;
    }
    if (customerFilter) {
      const hay = `${draft.customerName} ${draft.customerEmail}`.toLowerCase();
      if (!hay.includes(customerFilter.toLowerCase())) {
        base.status = "skipped";
        base.skipReason = `customer filter mismatch (${customerFilter})`;
        outcomes.push(base);
        continue;
      }
    }
    if (excludeSet.has(normalizeNo(draft.invoiceNo))) {
      base.status = "skipped";
      base.skipReason = "excluded";
      outcomes.push(base);
      continue;
    }
    if (!draft.customerEmail) {
      base.status = "skipped";
      base.skipReason = "no email on file";
      outcomes.push(base);
      continue;
    }
    if (draft.amountDue <= 0) {
      base.status = "skipped";
      base.skipReason = "no amount due";
      outcomes.push(base);
      continue;
    }
    if (cooldownDays > 0) {
      const lastEmailed = draft.lastSentIso && Number.isFinite(new Date(draft.lastSentIso).getTime()) ? draft.lastSentIso : null;
      if (lastEmailed && daysBetween(lastEmailed, nowDate) < cooldownDays) {
        base.status = "skipped";
        base.skipReason = `emailed ${lastEmailed.slice(0, 10)} (within ${cooldownDays}d cooldown)`;
        outcomes.push(base);
        continue;
      }
    }
    if (acted >= limit) {
      base.status = "skipped";
      base.skipReason = `over --limit (${limit})`;
      outcomes.push(base);
      continue;
    }
    acted++;
    if (!dryRun) {
      try {
        await doSend({
          id: draft.invoiceId,
          recipients: [draft.customerEmail],
          subject: draft.subject,
          message: draft.body
        });
        base.status = "sent";
      } catch (err2) {
        base.status = "failed";
        base.error = err2?.message || String(err2);
      }
    }
    outcomes.push(base);
  }
  const byStage = { gentle: 0, firm: 0, final: 0 };
  for (const o of outcomes) if (o.status !== "skipped") byStage[o.stage]++;
  return {
    dryRun,
    totalOverdue: rawInvoices.length,
    byStage,
    outcomes,
    planSkipped: plan.skipped,
    sent: outcomes.filter((o) => o.status === "sent").length,
    failed: outcomes.filter((o) => o.status === "failed").length,
    skipped: outcomes.filter((o) => o.status === "skipped").length
  };
}

