var CUSTOMERS_REMOVE_MANY_MUTATION = `
  mutation CustomersRemoveMany($filter: CompatRemoveOnecustomersInput!) {
    customersRemoveMany(filter: $filter) {
      records {
        recordId
        record {
          _id
          companyName
          firstName
          lastName
          individualCompanyName
          createdAt
          updatedAt
        }
      }
    }
  }
`;
async function deleteCustomer(id2) {
  const data = await bookipiGraphql({
    query: CUSTOMERS_REMOVE_MANY_MUTATION,
    variables: { filter: { _id: id2 } }
  });
  const removed = unwrapRemoveMany(
    data.customersRemoveMany?.records
  );
  if (!removed) throw new Error(`Customer not found: ${id2}`);
  return removed.record ?? { _id: removed.recordId };
}

