// src/core/formatters/EmailFormatter.ts
var EmailFormatter = class extends BaseFormatter {
  format(data, options) {
    if (options?.json === true) {
      return JSON.stringify(data, null, 2);
    }
    const page = Array.isArray(data) ? { items: data } : data ?? {};
    const items = page.items ?? [];
    const total = page.count ?? page.pageInfo?.itemCount ?? items.length;
    let output = `# Customer Emails (${total})
`;
    if (items.length === 0) {
      output += "\nNo emails found for this customer.\n";
      return output;
    }
    output += "\n_Dir: \u2192 sent to customer \xB7 \u2190 received from customer_\n\n";
    const headers = ["Date", "Dir", "Subject", "Opened", "Re"];
    const rows = items.map((e) => {
      const dir = e.isToCustomer ? "\u2192" : "\u2190";
      let subject = (e.subject || "(no subject)").trim();
      if (subject.length > 46) subject = subject.slice(0, 45) + "\u2026";
      if (e.attachments && e.attachments.length > 0) subject += " \u{1F4CE}";
      if (e.latestReply) subject += " \u21A9";
      const opened = e.bounced ? "bounced" : e.opened ? "\u2713" : "\u2014";
      const re2 = e.emailDocument?.no ? String(e.emailDocument.no) : e.emailProposal?.title || "\u2014";
      return [
        e.sendDate ? this.formatDate(e.sendDate) : "\u2014",
        dir,
        subject,
        opened,
        re2
      ];
    });
    output += this.createTable(headers, rows);
    const meta3 = page.pageInfo;
    if (meta3) {
      output += `
Page ${meta3.currentPage} of ${meta3.pageCount} (${meta3.itemCount} total)
`;
    }
    output += this.separator();
    output += this.nextActions("Notes", [
      "\u21A9 = has a reply \xB7 \u{1F4CE} = has attachments",
      "Next page: `bookipi customer emails <customer> --page 2`"
    ]);
    return output;
  }
};

