init_s3Upload();
import fs8 from "fs";
import path9 from "path";

// src/usecases/expense/getUploadUrl.ts
init_bookipiGraphql();
var GET_IMAGE_OCR_UPLOAD_URL_QUERY = `
  query GetImageOcrUploadUrl($ext: BookipayUploadExt!, $isThumbnail: Boolean) {
    getImageOCRUploadUrl(ext: $ext, isThumbnail: $isThumbnail) {
      url
      fields
    }
  }
`;
async function getImageOcrUploadUrl(opts) {
  const data = await bookipiGraphql({
    query: GET_IMAGE_OCR_UPLOAD_URL_QUERY,
    variables: { ext: opts.ext, isThumbnail: opts.isThumbnail ?? false }
  });
  const raw = data.getImageOCRUploadUrl;
  let fields = raw.fields;
  if (typeof fields === "string") {
    try {
      fields = JSON.parse(fields);
    } catch {
      throw new Error(
        "Upload presign response had a malformed `fields` payload \u2014 cannot build the S3 form."
      );
    }
  }
  return { url: raw.url, fields };
}

// src/usecases/expense/uploadToS3.ts
var EXT_TO_CONTENT_TYPE3 = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  pdf: "application/pdf",
  heic: "image/heic",
  webp: "image/webp"
};
async function uploadReceiptFile(opts) {
  const { filePath, isThumbnail = false } = opts;
  if (!fs8.existsSync(filePath)) {
    throw new Error(`File not found: ${filePath}`);
  }
  const extRaw = path9.extname(filePath).replace(/^\./, "").toLowerCase();
  if (!extRaw) {
    throw new Error(
      `File ${filePath} has no extension; cannot determine upload type`
    );
  }
  const ext = extRaw;
  const contentType3 = EXT_TO_CONTENT_TYPE3[extRaw] ?? "application/octet-stream";
  const presigned = await getImageOcrUploadUrl({ ext, isThumbnail });
  await postToS3(filePath, presigned, contentType3);
  const fullKey = presigned.fields["key"] ?? "";
  if (!fullKey) {
    throw new Error(
      "Upload succeeded but the presigned response had no `key` field \u2014 cannot reference the uploaded object"
    );
  }
  return {
    fullKey,
    filename: path9.basename(fullKey),
    contentType: contentType3
  };
}

