// src/core/auth/bpayToken.ts
init_config();
init_tokenStore();
function parseBpayRedirect(location) {
  const u = new URL(location);
  const token = u.searchParams.get("token");
  if (!token) {
    throw new Error("BPay auth redirect did not include a token.");
  }
  if (token === "undefined" || token === "null") {
    throw new Error(
      "This account isn't set up for payment links yet \u2014 open Payment Links in the Bookipi web app once to activate it, then try again."
    );
  }
  const companyId = u.searchParams.get("companyId");
  return {
    token,
    companyId: companyId === "undefined" || companyId === "null" ? null : companyId,
    onboardStatus: u.searchParams.get("onboardStatus"),
    acceptCardPayments: u.searchParams.get("acceptCardPayments") === "true"
  };
}
async function mintBpaySession() {
  const token = getToken();
  if (!token) throw new Error("Not logged in \u2014 run 'bookipi login' first.");
  const companyId = getDefaultCompany();
  if (!companyId) {
    throw new Error(
      "No default company set \u2014 run 'bookipi whoami' or 'bookipi login' first."
    );
  }
  const authUrl = `${config.BOOKIPI_URL}/payment-links/auth?token=${encodeURIComponent(token)}&companyId=${encodeURIComponent(companyId)}`;
  let res;
  try {
    res = await fetch(authUrl, {
      method: "GET",
      redirect: "manual",
      // we want the redirect target, not to follow it
      signal: AbortSignal.timeout(3e4)
    });
  } catch (err2) {
    const cause = err2?.name === "TimeoutError" ? "timed out" : err2?.cause?.message || err2?.message || "unknown";
    throw new Error(`Couldn't reach the BPay auth endpoint (${cause}).`);
  }
  const loc = res.headers.get("location");
  if (!loc) {
    throw new Error(
      `BPay auth didn't redirect (HTTP ${res.status}) \u2014 couldn't mint a payment token. Is your Bookipi session still valid?`
    );
  }
  return parseBpayRedirect(loc);
}
var sessionPromise = null;
function getBpaySession() {
  const override = process.env["BPAY_TOKEN"];
  if (override) {
    return Promise.resolve({
      token: override,
      companyId: null,
      onboardStatus: null,
      acceptCardPayments: false
    });
  }
  if (!sessionPromise) sessionPromise = mintBpaySession();
  return sessionPromise;
}

// src/core/api/bpayGraphql.ts
async function bpayGraphql({
  query,
  variables
}) {
  const { token } = await getBpaySession();
  return graphqlRequest({
    url: `${config.BPAY_URL}/gql`,
    query,
    variables,
    headers: {
      Authorization: `Bearer ${token}`
    }
  });
}

