// src/core/formatters/MeetingFormatter.ts
var MeetingFormatter = class extends BaseFormatter {
  registry;
  constructor() {
    super();
    this.registry = HandleRegistry.getInstance();
  }
  format(data, options) {
    const jsonMode = options?.json === true;
    if (jsonMode) {
      return JSON.stringify(data, null, 2);
    }
    if (Array.isArray(data)) {
      return this.formatList(data);
    }
    if (data?.getBookings?.items && Array.isArray(data.getBookings.items)) {
      return this.formatList(data.getBookings.items, data.getBookings.pagination);
    }
    return this.formatSingle(data);
  }
  formatList(meetings, meta3) {
    let output = `# Meetings (${meetings.length} found)
`;
    if (meetings.length === 0) {
      output += "\nNo meetings found.\n";
      return output;
    }
    const headers = ["Handle", "When", "Title", "With", "Duration", "Status"];
    const rows = meetings.map((meeting) => {
      const id2 = meeting._id || "unknown";
      const handle = this.registry.register("m", id2);
      const when = this.formatWhen(meeting.start, meeting.timezone);
      const title = meeting.name || meeting.link?.title || "Untitled";
      const withWho = this.getCounterpart(meeting);
      const duration3 = meeting.link?.duration ? `${meeting.link.duration}m` : this.computeDuration(meeting.start, meeting.end);
      const status = this.formatStatus(meeting.status);
      return [handle, when, title, withWho, duration3, status];
    });
    output += "\n";
    output += this.createTable(headers, rows);
    if (meta3) {
      output += "\n";
      const page = meta3.page ?? 1;
      const pageSize = meta3.pageSize ?? meetings.length;
      const totalItems = meta3.totalItems ?? meetings.length;
      const totalPages = meta3.totalPages ?? 1;
      output += `Page ${page} of ${totalPages} (${totalItems} total, ${pageSize} per page)
`;
    }
    return output;
  }
  formatSingle(meeting) {
    const id2 = meeting._id || "unknown";
    const handle = this.registry.register("m", id2);
    const title = meeting.name || meeting.link?.title || "Untitled meeting";
    let output = `# Meeting: ${title} [${handle}]
`;
    output += this.section("When");
    output += this.listItem("Start", this.formatWhen(meeting.start, meeting.timezone));
    if (meeting.end) {
      output += this.listItem("End", this.formatWhen(meeting.end, meeting.timezone));
    }
    if (meeting.link?.duration) {
      output += this.listItem("Duration", `${meeting.link.duration} minutes`);
    }
    if (meeting.timezone) {
      output += this.listItem("Timezone", meeting.timezone);
    }
    output += this.section("With");
    output += this.listItem("Counterpart", this.getCounterpart(meeting));
    if (meeting.email) output += this.listItem("Email", meeting.email);
    if (meeting.guests && meeting.guests.length > 0) {
      output += this.listItem("Guests", meeting.guests.join(", "));
    }
    output += this.section("Details");
    if (meeting.status) output += this.listItem("Status", this.formatStatus(meeting.status));
    if (meeting.location) output += this.listItem("Location", meeting.location);
    if (meeting.link?.title) output += this.listItem("Booking link", meeting.link.title);
    if (meeting.notes) output += this.listItem("Notes", meeting.notes);
    if (meeting.summary) output += this.listItem("Summary", meeting.summary);
    const transcript = meeting.transcription?.meetingSummary;
    if (transcript) {
      output += this.section("Transcript / AI Summary");
      if (transcript.status) output += this.listItem("Status", transcript.status);
      if (transcript.text) output += this.listItem("Text", transcript.text);
      if (transcript.notes) output += this.listItem("Notes", transcript.notes);
      if (transcript.actions && transcript.actions.length > 0) {
        output += this.listItem("Actions", transcript.actions.join("; "));
      }
      if (transcript.failureReason) {
        output += this.listItem("Failure", transcript.failureReason);
      }
    }
    return output;
  }
  getCounterpart(meeting) {
    if (meeting.email) return meeting.email;
    const c = meeting.customer;
    if (c) {
      const fullName = [c.firstName, c.lastName].filter(Boolean).join(" ").trim();
      if (fullName) return fullName;
    }
    return "Unknown";
  }
  formatWhen(iso, timezone) {
    if (!iso) return "N/A";
    try {
      const d = new Date(iso);
      if (timezone) {
        return d.toLocaleString("en-US", {
          timeZone: timezone,
          year: "numeric",
          month: "short",
          day: "numeric",
          hour: "2-digit",
          minute: "2-digit",
          hour12: false
        });
      }
      return d.toISOString();
    } catch {
      return iso;
    }
  }
  computeDuration(startIso, endIso) {
    if (!startIso || !endIso) return "N/A";
    try {
      const ms = new Date(endIso).getTime() - new Date(startIso).getTime();
      if (!Number.isFinite(ms) || ms <= 0) return "N/A";
      return `${Math.round(ms / 6e4)}m`;
    } catch {
      return "N/A";
    }
  }
};

