// src/usecases/proposal/draftProposal.ts
var DEFAULT_CONTRACT_MONTHS = 36;
var DEFAULT_EXPIRY_DAYS = 30;
function lineFromItem(row) {
  const price = row["price"] ?? 0;
  return {
    itemId: row["_id"],
    name: row["name"],
    price,
    quantity: 1,
    totalAmount: price,
    description: row["description"] ?? "",
    productCode: row["productCode"] ?? "",
    // "acceptance" bills when the proposal is accepted, which is what a
    // proposal line means; the API has no sensible default.
    billingType: "acceptance"
  };
}
async function resolveItem2(ref) {
  if (typeof ref !== "string") {
    const quantity = ref.quantity ?? 1;
    return {
      ...ref.itemId ? { itemId: ref.itemId } : {},
      name: ref.name,
      price: ref.price,
      quantity,
      totalAmount: ref.price * quantity,
      description: ref.description ?? "",
      productCode: ref.productCode ?? "",
      billingType: ref.billingType ?? "acceptance"
    };
  }
  if (/^[a-f0-9]{24}$/i.test(ref)) {
    const item = await getItemById(ref);
    if (!item) throw new Error(`Item ${ref} not found.`);
    return lineFromItem(item);
  }
  const search = await listItems({ search: ref, perPage: 5 });
  const matches = search.searchItems?.items ?? [];
  if (matches.length > 0) {
    const exact = matches.find(
      (i) => String(i["name"] ?? "").toLowerCase() === ref.trim().toLowerCase()
    );
    return lineFromItem(exact ?? matches[0]);
  }
  throw new Error(
    `Item "${ref}" not found. Pass an existing item id, or state the line outright as { name, price, quantity }.`
  );
}
async function draftProposal(input) {
  if (!input.items || input.items.length === 0) {
    throw new Error(
      "A proposal needs at least one service item \u2014 there is nothing to accept without one."
    );
  }
  if (!input.description?.trim()) {
    throw new Error("A proposal needs a description to generate from.");
  }
  const expiresIn = input.expiresInDays ?? DEFAULT_EXPIRY_DAYS;
  if (!Number.isFinite(expiresIn) || expiresIn < 1) {
    throw new Error("expiresInDays must be a positive number of days.");
  }
  const contractLength = input.contractLength ?? DEFAULT_CONTRACT_MONTHS;
  if (!Number.isFinite(contractLength) || contractLength < 1) {
    throw new Error("contractLength must be a positive number of months.");
  }
  const serviceItems = [];
  for (const ref of input.items) serviceItems.push(await resolveItem2(ref));
  const startDate = input.startDate ? new Date(input.startDate).toISOString() : (/* @__PURE__ */ new Date()).toISOString();
  const expirationDate = new Date(
    new Date(startDate).getTime() + expiresIn * 24 * 60 * 60 * 1e3
  ).toISOString();
  const data = await generateProposal({
    businessDescription: input.description,
    serviceItems,
    contractLength,
    startDate,
    endDate: startDate,
    effectiveDate: startDate,
    expirationDate,
    paymentEnabled: !!input.paymentEnabled,
    ...input.customerId ? { customerId: input.customerId } : {},
    ...input.dealId ? { projectPipelineId: input.dealId } : {},
    ...input.extra ?? {}
  });
  const proposal = data.proposalsAiWithContentCreateOne?.record;
  if (!proposal) {
    throw new Error(
      "Generation succeeded but no record was returned \u2014 check the API response shape."
    );
  }
  return {
    proposal,
    editUrlPlain: `${config.BOOKIPI_WEB_URL}/pitch/proposals/ai/edit/${String(proposal["_id"])}`
  };
}

