// src/usecases/company/setDefaultCompany.ts
init_tokenStore();
async function setDefaultCompany(idOrName) {
  const trimmed = idOrName.trim();
  if (!trimmed) {
    throw new Error("Company id or name cannot be empty.");
  }
  const data = await whoami();
  const rawCompanies = data?.whoami?.companies ?? [];
  if (rawCompanies.length === 0) {
    throw new Error("No companies found on this account.");
  }
  const isObjectId = /^[0-9a-f]{24}$/i.test(trimmed);
  if (isObjectId) {
    const matched2 = rawCompanies.find(
      (c) => c._id.toLowerCase() === trimmed.toLowerCase()
    );
    if (!matched2) {
      const available = rawCompanies.map((c) => `${c._id} ${c.name}`).join(", ");
      throw new Error(
        `No company found with id ${trimmed}. Available companies: ${available}`
      );
    }
    saveDefaultCompany(matched2._id);
    return {
      company: {
        _id: matched2._id,
        name: matched2.name,
        currency: matched2.currency ?? ""
      }
    };
  }
  const normalised = trimmed.toLowerCase();
  const matches = rawCompanies.filter(
    (c) => c.name.trim().toLowerCase() === normalised
  );
  if (matches.length === 0) {
    const names = rawCompanies.map((c) => c.name).join(", ");
    throw new Error(
      `No company found matching '${trimmed}'. Available companies: ${names}`
    );
  }
  if (matches.length > 1) {
    const listed = matches.map((c) => `${c._id} ${c.name}`).join(", ");
    throw new Error(
      `Multiple companies named '${trimmed}': [${listed}]. Use an _id instead.`
    );
  }
  const matched = matches[0];
  saveDefaultCompany(matched._id);
  return {
    company: {
      _id: matched._id,
      name: matched.name,
      currency: matched.currency ?? ""
    }
  };
}

