var setCommand = new Command("set").description("Set the default company by ID or name").argument("<id-or-name>", "Company _id (24-char hex) or name (case-insensitive)").option("--json", "Output raw JSON instead of formatted").action(async (idOrName, opts) => {
  try {
    if (idOrName.trim() === "") {
      failWith("Company id or name cannot be empty.", { json: opts?.json });
    }
    const result = await setDefaultCompany(idOrName.trim());
    if (opts.json) {
      console.log(JSON.stringify({ success: true, company: result.company }, null, 2));
    } else {
      console.log(
        `\u2705 Default company changed to: ${result.company.name} [${result.company.currency}]`
      );
    }
    if (process.env.BOOKIPI_COMPANY) {
      process.stderr.write(
        `\u26A0 BOOKIPI_COMPANY env var is set (= ${process.env.BOOKIPI_COMPANY}). It will override the saved default at runtime.
`
      );
    }
  } catch (err2) {
    emitError(err2, { json: opts?.json });
  }
});

